-- Adapted for MedFlow V7: original clinical data and logical identifiers preserved.
-- MedFlow • demo seed v1 • PostgreSQL 16, schema initiala V1__initial_schema.sql.
-- TOATE datele sunt fictive, exclusiv pentru demonstratie si dezvoltare.
-- NU este un set validat pentru diagnostic, tratament sau triaj real.
-- Necesita existenta celor 8 tabele din MVP. Nu sterge sau modifica inregistrarile existente.
-- Rulare: docker compose exec -T db psql -U hospital -d hospital -v ON_ERROR_STOP=1 < seed_medflow.sql
-- Rerulabil: se evita dublurile pe identificatorii logici prefixati MFSEED.

BEGIN;
CREATE TEMP TABLE mf_seed_clinical_cases (
   seq INTEGER PRIMARY KEY,
   synthetic_case_id VARCHAR(30) NOT NULL UNIQUE,
   symptoms TEXT NOT NULL,
   observations TEXT NOT NULL,
   assessment TEXT NOT NULL,
   category VARCHAR(40) NOT NULL,
   summary TEXT NOT NULL,
   evidence TEXT NOT NULL
) ON COMMIT DROP;

-- Current-schema adapter: append-only, one transaction, all constraints remain active.
SET LOCAL lock_timeout = '15s';
SET LOCAL statement_timeout = '180s';
SELECT pg_advisory_xact_lock(760011170001::bigint);
DO $preflight$
DECLARE relation_name TEXT;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY['hospitals','doctors','patients','app_users','appointments','encounters','ai_analyses','audit_events','work_periods'] LOOP
    IF to_regclass('public.' || relation_name) IS NULL THEN
      RAISE EXCEPTION 'Lipseste tabela %. Porneste backendul actualizat pentru migrarea schemei.', relation_name;
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT FROM information_schema.columns
    WHERE table_schema='public' AND table_name='appointments' AND column_name='version') THEN
    RAISE EXCEPTION 'Importul adaptat necesita schema V7. Actualizeaza backendul inainte de import.';
  END IF;
END
$preflight$;

CREATE FUNCTION pg_temp.mf_seed_ensure_work_period(h BIGINT, d BIGINT, appointment_start TIMESTAMP)
RETURNS VOID LANGUAGE plpgsql AS $work_period$
DECLARE
  preferred_start TIMESTAMP := LEAST(date_trunc('day',appointment_start)+interval '8 hours',appointment_start);
  preferred_end TIMESTAMP := GREATEST(date_trunc('day',appointment_start)+interval '18 hours',appointment_start+interval '30 minutes');
BEGIN
  PERFORM id FROM doctors WHERE hospital_id=h AND id=d FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Medicul % nu apartine spitalului %.',d,h; END IF;
  IF EXISTS (SELECT FROM work_periods WHERE hospital_id=h AND doctor_id=d
      AND start_at<=appointment_start AND end_at>=appointment_start+interval '30 minutes') THEN RETURN; END IF;
  IF NOT EXISTS (SELECT FROM work_periods WHERE hospital_id=h AND doctor_id=d
      AND start_at<preferred_end AND end_at>preferred_start) THEN
  ELSIF NOT EXISTS (SELECT FROM work_periods WHERE hospital_id=h AND doctor_id=d
      AND start_at<appointment_start+interval '30 minutes' AND end_at>appointment_start) THEN
      VALUES(h,d,appointment_start,appointment_start+interval '30 minutes');
  ELSE
    RAISE EXCEPTION 'Program existent incompatibil cu programarea importata: spital %, medic %, ora %. Nicio inregistrare existenta nu a fost modificata.',h,d,appointment_start;
  END IF;
END
$work_period$;




















DO $medflow_seed$
DECLARE
  -- Numarul de inregistrari noi (in afara celor deja existente in DB):
  -- 100 hospitals, 400 doctors, 1450 patients, 2400 appointments,
  -- 1080 encounters, 720 ai_analyses, 420 app_users, 1040 audit_events.
  v_password_hash TEXT := '$2y$10$bnRoUQ.VUvNJK9LkkM1EE.bbkhvsb2mU4mxs1tGmZNekkVL4noyKm';
  v_hospital_id BIGINT;
  v_doctor_id BIGINT;
  v_patient_id BIGINT;
  v_appointment_id BIGINT;
  v_encounter_id BIGINT;
  v_actor_id BIGINT;
  v_doctor_ids BIGINT[];
  v_patient_ids BIGINT[];
  v_date TIMESTAMP;
  v_status TEXT;
  v_name TEXT;
  v_email TEXT;
  v_tag TEXT;
  v_hosp_code TEXT;
  v_doctor_code TEXT;
  v_patient_code TEXT;
  v_reason TEXT;
  v_idx INTEGER;
  v_hidx INTEGER;
  v_didx INTEGER;
  v_pidx INTEGER;
  v_appt_count INTEGER;
  v_visit_count INTEGER;
  v_ai_count INTEGER;
  v_template_seq INTEGER;
  v_first_names TEXT[] := ARRAY['Ana','Mihai','Elena','Andrei','Ioana','Radu','Maria','Victor','Irina','Alexandru','Teodora','Daria','Matei','Cristina','Paul','Diana','Luca','Sofia','Oana','Vlad'];
  v_last_names TEXT[] := ARRAY['Popescu','Ionescu','Georgescu','Marinescu','Dumitrescu','Radu','Stan','Petrescu','Munteanu','Stoica','Florea','Sandu','Tudor','Enache','Ilie','Nistor','Dobre','Badea','Preda','Matei'];
  v_specialties TEXT[] := ARRAY['Medicina interna','Cardiologie','Medicina de familie','Pediatrie','Neurologie','Pneumologie','Dermatologie','Endocrinologie','Ortopedie','Gastroenterologie'];
  v_cities TEXT[] := ARRAY['Bucuresti','Cluj-Napoca','Iasi','Timisoara','Brasov','Constanta','Craiova','Oradea','Sibiu','Galati'];
  v_reasons TEXT[] := ARRAY['Control de rutina','Evaluare simptomatologie','Consult programat','Monitorizare periodica','Evaluare generala'];
  v_case RECORD;
BEGIN
  -- 1. Spitalul demonstrativ EXISTENT, folosit de admin@demo.ro.
  --    Daca lipseste, il cream; nu schimbam conturile deja existente.
  SELECT hospital_id INTO v_hospital_id FROM app_users WHERE lower(email)='admin@demo.ro' AND role='ADMIN' LIMIT 1;
  IF v_hospital_id IS NULL THEN
    SELECT id INTO v_hospital_id FROM hospitals WHERE name='Spitalul Demo București' ORDER BY id LIMIT 1;
  END IF;
  IF v_hospital_id IS NULL THEN
    VALUES ('Spitalul Demo București', 'Bucuresti - date integral fictive') RETURNING id INTO v_hospital_id;
  END IF;
  v_hosp_code := 'DEMO';
  v_doctor_ids := ARRAY[]::BIGINT[];
  v_patient_ids := ARRAY[]::BIGINT[];

  -- 100 medici suplimentari in spitalul vizibil in contul demo.
  FOR v_idx IN 1..100 LOOP
    v_doctor_code := lpad(v_idx::TEXT,4,'0');
    v_email := 'demo.doctor' || v_doctor_code || '@medflow.example.test';
    SELECT id INTO v_doctor_id FROM doctors WHERE hospital_id=v_hospital_id AND lower(email)=lower(v_email) ORDER BY id LIMIT 1;
    IF v_doctor_id IS NULL THEN
      v_name := 'Dr. ' || v_first_names[1+((v_idx-1)%cardinality(v_first_names))] || ' ' ||
        v_last_names[1+(((v_idx-1)/cardinality(v_first_names))%cardinality(v_last_names))];
      VALUES (v_hospital_id,v_name,v_specialties[1+((v_idx-1)%cardinality(v_specialties))],v_email)
      RETURNING id INTO v_doctor_id;
    END IF;
    v_doctor_ids := array_append(v_doctor_ids,v_doctor_id);
  END LOOP;

  -- 250 pacienti suplimentari in demo; e-mail-uri de test .test.
  FOR v_idx IN 1..250 LOOP
    v_patient_code := lpad(v_idx::TEXT,4,'0');
    v_email := 'demo.patient' || v_patient_code || '@medflow.example.test';
    SELECT id INTO v_patient_id FROM patients WHERE hospital_id=v_hospital_id AND lower(email)=lower(v_email) ORDER BY id LIMIT 1;
    IF v_patient_id IS NULL THEN
      VALUES (v_hospital_id,
        v_first_names[1+((v_idx-1)%cardinality(v_first_names))],
        v_last_names[1+(((v_idx-1)/cardinality(v_first_names))%cardinality(v_last_names))],
        DATE '1945-01-01'+((v_idx*83)%22000),
        '0700' || lpad(v_idx::TEXT,6,'0'),v_email,
        current_timestamp-((v_idx%45)+1)*interval '1 day')
      RETURNING id INTO v_patient_id;
    END IF;
    v_patient_ids := array_append(v_patient_ids,v_patient_id);
  END LOOP;

  -- 120 conturi de autentificare noi: 20 ADMIN + 40 DOCTOR + 60 PATIENT.
  FOR v_idx IN 1..20 LOOP
    v_email := 'demo.admin' || lpad(v_idx::TEXT,4,'0') || '@medflow.example.test';
    VALUES (v_hospital_id,'Administrator fictiv '||v_idx,v_email,v_password_hash,'ADMIN',NULL,NULL)
    ON CONFLICT DO NOTHING;
  END LOOP;
  FOR v_idx IN 1..40 LOOP
    v_doctor_id := v_doctor_ids[v_idx];
    SELECT name,email INTO v_name,v_email FROM doctors WHERE id=v_doctor_id;
    VALUES (v_hospital_id,v_name,v_email,v_password_hash,'DOCTOR',v_doctor_id,NULL)
    ON CONFLICT DO NOTHING;
  END LOOP;
  FOR v_idx IN 1..60 LOOP
    v_patient_id := v_patient_ids[v_idx];
    SELECT first_name || ' ' || last_name,email INTO v_name,v_email FROM patients WHERE id=v_patient_id;
    VALUES (v_hospital_id,v_name,v_email,v_password_hash,'PATIENT',NULL,v_patient_id)
    ON CONFLICT DO NOTHING;
  END LOOP;
  SELECT id INTO v_actor_id FROM app_users WHERE hospital_id=v_hospital_id AND lower(email)='demo.admin0001@medflow.example.test' LIMIT 1;
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Lipseste contul fictiv admin pentru audit in spitalul demo';
  END IF;

  FOR v_idx IN 1..400 LOOP
    v_doctor_id := v_doctor_ids[1+((v_idx-1)%100)];
    v_patient_id := v_patient_ids[1+(((v_idx-1)*13)%250)];
    v_reason := '[MFSEED:DEMO:A' || lpad(v_idx::TEXT,4,'0') || '] ' ||
       v_reasons[1+((v_idx-1)%cardinality(v_reasons))];
    IF v_idx <= 180 THEN
      v_status:='COMPLETED';
      v_date := (current_date-((v_idx%80)+1))::timestamp +
        make_interval(hours=>8+(v_idx%8), mins=>(v_idx%2)*30);
    ELSIF v_idx%8=0 THEN
      v_status:='CANCELLED';
      v_date := (current_date+((v_idx%40)+1))::timestamp +
        make_interval(hours=>8+(v_idx%8), mins=>(v_idx%2)*30);
    ELSE
      v_status:='SCHEDULED';
      v_date := (current_date+((v_idx%45)+1))::timestamp +
        make_interval(hours=>8+(v_idx%8), mins=>(v_idx%2)*30);
    END IF;
    SELECT id INTO v_appointment_id FROM appointments
      WHERE hospital_id=v_hospital_id AND reason=v_reason ORDER BY id LIMIT 1;
    IF v_appointment_id IS NULL THEN
      IF v_status='SCHEDULED' THEN PERFORM pg_temp.mf_seed_ensure_work_period(v_hospital_id,v_doctor_id,v_date); END IF;
      VALUES(v_hospital_id,v_patient_id,v_doctor_id,v_date,v_reason,v_status,
        LEAST(current_timestamp-interval '1 day',v_date-interval '3 days'))
      RETURNING id INTO v_appointment_id;
    END IF;
    IF v_idx <= 180 THEN
      SELECT * INTO v_case FROM mf_seed_clinical_cases WHERE seq=v_idx;
      SELECT id INTO v_encounter_id FROM encounters
        WHERE hospital_id=v_hospital_id AND appointment_id=v_appointment_id
          ORDER BY id LIMIT 1;
      IF v_encounter_id IS NULL THEN
        VALUES (v_hospital_id,v_patient_id,v_doctor_id,v_appointment_id,
          v_case.symptoms,v_case.observations,v_case.assessment,v_date)
        RETURNING id INTO v_encounter_id;
      END IF;
      IF v_idx <= 120 THEN
        SELECT v_hospital_id,v_encounter_id,v_case.category,v_case.summary,v_case.evidence,
            'seed-fixture-synthetic-1.0',v_date+interval '30 minutes'
        WHERE NOT EXISTS (SELECT 1 FROM ai_analyses
            WHERE encounter_id=v_encounter_id AND model_version='seed-fixture-synthetic-1.0');
      END IF;
    END IF;
  END LOOP;
  FOR v_idx IN 1..240 LOOP
    v_tag := 'MFSEED:DEMO:EVENT' || lpad(v_idx::TEXT,4,'0');
    SELECT v_hospital_id,v_actor_id,'DEMO_IMPORT',v_tag,
       current_timestamp-((v_idx%80)+1)*interval '1 hour'
    WHERE NOT EXISTS (SELECT 1 FROM audit_events
      WHERE hospital_id=v_hospital_id AND action='DEMO_IMPORT' AND resource=v_tag);
  END LOOP;

  -- 2. 100 spitale integral fictive, separat logic pe hospital_id.
  FOR v_hidx IN 1..100 LOOP
    v_hosp_code := 'H' || lpad(v_hidx::TEXT,3,'0');
    v_name := 'Spital fictiv MedFlow ' || lpad(v_hidx::TEXT,3,'0');
    SELECT id INTO v_hospital_id FROM hospitals WHERE name=v_name ORDER BY id LIMIT 1;
    IF v_hospital_id IS NULL THEN
      VALUES(v_name,v_cities[1+((v_hidx-1)%cardinality(v_cities))] ||
        ', Romania - adresa fictiva pentru testare')
      RETURNING id INTO v_hospital_id;
    END IF;
    v_doctor_ids:=ARRAY[]::BIGINT[];
    v_patient_ids:=ARRAY[]::BIGINT[];

    FOR v_didx IN 1..3 LOOP
      v_email := 'hospital' || lpad(v_hidx::TEXT,3,'0') || '.doctor' || v_didx || '@medflow.example.test';
      SELECT id INTO v_doctor_id FROM doctors WHERE hospital_id=v_hospital_id AND lower(email)=lower(v_email) ORDER BY id LIMIT 1;
      IF v_doctor_id IS NULL THEN
        v_name:='Dr. ' || v_first_names[1+((v_hidx+v_didx-1)%cardinality(v_first_names))] ||
          ' ' || v_last_names[1+((v_hidx*3+v_didx)%cardinality(v_last_names))];
        VALUES(v_hospital_id,v_name,v_specialties[1+((v_hidx+v_didx-2)%cardinality(v_specialties))],v_email)
        RETURNING id INTO v_doctor_id;
      END IF;
      v_doctor_ids:=array_append(v_doctor_ids,v_doctor_id);
    END LOOP;

    FOR v_pidx IN 1..12 LOOP
      v_email := 'hospital' || lpad(v_hidx::TEXT,3,'0') || '.patient' || lpad(v_pidx::TEXT,2,'0') || '@medflow.example.test';
      SELECT id INTO v_patient_id FROM patients WHERE hospital_id=v_hospital_id AND lower(email)=lower(v_email) ORDER BY id LIMIT 1;
      IF v_patient_id IS NULL THEN
        VALUES(v_hospital_id,
          v_first_names[1+((v_hidx+v_pidx-1)%cardinality(v_first_names))],
          v_last_names[1+((v_hidx*7+v_pidx)%cardinality(v_last_names))],
          DATE '1950-01-01'+((v_hidx*71+v_pidx*467)%21000),
          '0701' || lpad((v_hidx*100+v_pidx)::TEXT,6,'0'),v_email,
          current_timestamp-((v_pidx%40)+1)*interval '1 day')
        RETURNING id INTO v_patient_id;
      END IF;
      v_patient_ids:=array_append(v_patient_ids,v_patient_id);
    END LOOP;

    -- Cate un cont din fiecare rol pentru fiecare spital.
    v_email := 'hospital' || lpad(v_hidx::TEXT,3,'0') || '.admin@medflow.example.test';
    VALUES(v_hospital_id,'Administrator fictiv ' || v_hosp_code,v_email,v_password_hash,'ADMIN',NULL,NULL)
    ON CONFLICT DO NOTHING;
    SELECT id INTO v_actor_id FROM app_users WHERE hospital_id=v_hospital_id AND lower(email)=lower(v_email) LIMIT 1;
    v_doctor_id:=v_doctor_ids[1];
    SELECT name,email INTO v_name,v_email FROM doctors WHERE id=v_doctor_id;
    VALUES(v_hospital_id,v_name,v_email,v_password_hash,'DOCTOR',v_doctor_id,NULL)
    ON CONFLICT DO NOTHING;
    v_patient_id:=v_patient_ids[1];
    SELECT first_name||' '||last_name,email INTO v_name,v_email FROM patients WHERE id=v_patient_id;
    VALUES(v_hospital_id,v_name,v_email,v_password_hash,'PATIENT',NULL,v_patient_id)
    ON CONFLICT DO NOTHING;

    FOR v_idx IN 1..20 LOOP
      v_doctor_id:=v_doctor_ids[1+((v_idx-1)%3)];
      v_patient_id:=v_patient_ids[1+((v_idx-1)%12)];
      v_reason:='[MFSEED:'||v_hosp_code||':A'||lpad(v_idx::TEXT,3,'0')||'] '||
          v_reasons[1+((v_idx-1)%cardinality(v_reasons))];
      IF v_idx<=9 THEN
        v_status:='COMPLETED';
        v_date:=(current_date-((v_idx%38)+1))::timestamp+
          make_interval(hours=>8+(v_idx%8),mins=>(v_idx%2)*30);
      ELSIF v_idx=20 THEN
        v_status:='CANCELLED';
        v_date:=(current_date+((v_idx%35)+1))::timestamp+
          make_interval(hours=>8+(v_idx%8),mins=>(v_idx%2)*30);
      ELSE
        v_status:='SCHEDULED';
        v_date:=(current_date+((v_idx%35)+1))::timestamp+
          make_interval(hours=>8+(v_idx%8),mins=>(v_idx%2)*30);
      END IF;
      SELECT id INTO v_appointment_id FROM appointments
        WHERE hospital_id=v_hospital_id AND reason=v_reason ORDER BY id LIMIT 1;
      IF v_appointment_id IS NULL THEN
        IF v_status='SCHEDULED' THEN PERFORM pg_temp.mf_seed_ensure_work_period(v_hospital_id,v_doctor_id,v_date); END IF;
        VALUES(v_hospital_id,v_patient_id,v_doctor_id,v_date,v_reason,v_status,
          LEAST(current_timestamp-interval '1 day',v_date-interval '2 days'))
        RETURNING id INTO v_appointment_id;
      END IF;
      IF v_idx<=9 THEN
        v_template_seq:=180+(v_hidx-1)*9+v_idx;
        SELECT * INTO v_case FROM mf_seed_clinical_cases WHERE seq=v_template_seq;
        SELECT id INTO v_encounter_id FROM encounters
          WHERE hospital_id=v_hospital_id AND appointment_id=v_appointment_id
            ORDER BY id LIMIT 1;
        IF v_encounter_id IS NULL THEN
          VALUES(v_hospital_id,v_patient_id,v_doctor_id,v_appointment_id,
            v_case.symptoms,v_case.observations,v_case.assessment,v_date)
          RETURNING id INTO v_encounter_id;
        END IF;
        IF v_idx<=6 THEN
          SELECT v_hospital_id,v_encounter_id,v_case.category,v_case.summary,v_case.evidence,
            'seed-fixture-synthetic-1.0',v_date+interval '30 minutes'
          WHERE NOT EXISTS (SELECT 1 FROM ai_analyses
             WHERE encounter_id=v_encounter_id AND model_version='seed-fixture-synthetic-1.0');
        END IF;
      END IF;
    END LOOP;
    FOR v_idx IN 1..8 LOOP
      v_tag:='MFSEED:'||v_hosp_code||':EVENT'||lpad(v_idx::TEXT,3,'0');
      SELECT v_hospital_id,v_actor_id,'DEMO_IMPORT',v_tag,
          current_timestamp-((v_idx%60)+1)*interval '1 hour'
      WHERE NOT EXISTS(SELECT 1 FROM audit_events
           WHERE hospital_id=v_hospital_id AND action='DEMO_IMPORT' AND resource=v_tag);
    END LOOP;
  END LOOP;
  RAISE NOTICE 'MedFlow seed demo: toate entitatile au fost procesate (fara stergere/actualizare de date existente).';
END
$medflow_seed$;

-- Assertions execute BEFORE COMMIT, so an incomplete import rolls back in full.
DO $verify$
DECLARE n BIGINT;
BEGIN
  IF (SELECT count(*) FROM mf_seed_clinical_cases)<>1080 THEN
    RAISE EXCEPTION 'Setul clinic nu contine cele 1080 de cazuri asteptate.';
  END IF;
  SELECT count(*) INTO n FROM hospitals
    WHERE name IN (SELECT 'Spital fictiv MedFlow '||lpad(i::text,3,'0') FROM generate_series(1,100) AS g(i));
  IF n<>100 THEN RAISE EXCEPTION 'Spitale sintetice: %, asteptat 100.',n; END IF;
  IF (SELECT count(*) FROM doctors WHERE lower(email) LIKE 'demo.doctor%@medflow.example.test'
      OR lower(email) LIKE 'hospital%.doctor%@medflow.example.test')<400 THEN
    RAISE EXCEPTION 'Lipsesc profiluri de medic din setul importat.';
  END IF;
  IF (SELECT count(*) FROM patients WHERE lower(email) LIKE 'demo.patient%@medflow.example.test'
      OR lower(email) LIKE 'hospital%.patient%@medflow.example.test')<1450 THEN
    RAISE EXCEPTION 'Lipsesc pacienti din setul importat.';
  END IF;
  IF (SELECT count(*) FROM app_users WHERE lower(email) LIKE 'demo.%@medflow.example.test'
      OR lower(email) LIKE 'hospital%@medflow.example.test')<420 THEN
    RAISE EXCEPTION 'Lipsesc conturi din setul importat.';
  END IF;
  IF (SELECT count(*) FROM appointments WHERE reason LIKE '[MFSEED:%')<2400 THEN
    RAISE EXCEPTION 'Lipsesc programari din setul importat.';
  END IF;
  IF (SELECT count(*) FROM encounters e JOIN appointments a ON a.id=e.appointment_id
      WHERE a.reason LIKE '[MFSEED:%' )<1080 THEN
    RAISE EXCEPTION 'Lipsesc consultatii din setul importat.';
  END IF;
  IF (SELECT count(*) FROM ai_analyses WHERE model_version='seed-fixture-synthetic-1.0')<720 THEN
    RAISE EXCEPTION 'Lipsesc etichete AI sintetice din setul importat.';
  END IF;
  IF (SELECT count(*) FROM audit_events WHERE action='DEMO_IMPORT' AND resource LIKE 'MFSEED:%')<1040 THEN
    RAISE EXCEPTION 'Lipsesc evenimente de audit din setul importat.';
  END IF;
  IF EXISTS(SELECT FROM appointments a WHERE a.reason LIKE '[MFSEED:%' AND a.status='SCHEDULED'
      AND NOT EXISTS(SELECT FROM work_periods w WHERE w.hospital_id=a.hospital_id AND w.doctor_id=a.doctor_id
        AND w.start_at<=a.start_at AND w.end_at>=a.start_at+interval '30 minutes')) THEN
    RAISE EXCEPTION 'Exista programari importate in afara programului medicului.';
  END IF;
END
$verify$;

COMMIT;

-- Rezumatul dupa import (inclusiv inregistrarile care existau deja):
SELECT 'hospitals' AS tabela, COUNT(*) AS total FROM hospitals
UNION ALL SELECT 'doctors', COUNT(*) FROM doctors
UNION ALL SELECT 'patients', COUNT(*) FROM patients
UNION ALL SELECT 'app_users', COUNT(*) FROM app_users
UNION ALL SELECT 'appointments', COUNT(*) FROM appointments
UNION ALL SELECT 'encounters', COUNT(*) FROM encounters
UNION ALL SELECT 'ai_analyses', COUNT(*) FROM ai_analyses
UNION ALL SELECT 'audit_events', COUNT(*) FROM audit_events;
